use vstd::prelude::*;

verus! {

spec fn is_digit(c: char) -> bool {
    '0' <= c && c <= '9'
}

spec fn all_digits(s: Seq<char>) -> bool {
    forall|i: int| 0 <= i < s.len() ==> is_digit(s[i])
}

fn is_integer(text: &Vec<char>) -> (res: bool)
    ensures
        res == all_digits(text@),
{
    for &ch in text.iter()
        invariant
            // Prefix processed so far consists only of digits.
            forall|i: int| 0 <= i < text@.len() - text.iter().len() ==> is_digit(text@[i]),
    {
        if ch < '0' || ch > '9' {
            // `ch` is the next unprocessed element, so the whole sequence is not all digits.
            assert(!all_digits(text@));
            return false;
        }
    }
    assert(all_digits(text@));
    true
}

}

